project/material_manual.gdshader.content:
shader_type spatial;
#include "res://material_manual.gdshaderinc"
uniform mat3 basis_value;
uniform vec4 local_tint = vec4(1.0);
global uniform vec4 step5_global;
instance uniform vec4 instance_tint = vec4(1.0);
uniform sampler2D nearest_map : filter_nearest, repeat_enable;
uniform sampler2D linear_map : filter_linear, repeat_disable;
void fragment() {
    mat3 a = basis_value;
    mat3 b = mat3(vec3(0.5, 0.2, 0.1), vec3(0.1, 0.4, 0.0), vec3(0.0, 0.1, 0.3));
    vec3 v = vec3(0.3, 0.5, 0.7);
    int column = clamp(int(UV.x * 8.0), 0, 7);
    vec3 calculated = vec3(0.0);
    vec3 reference = vec3(0.0);
    if (column == 0) { calculated = a * v; reference = vec3(0.130000000, 0.180000000, 0.330000000); }
    if (column == 1) { calculated = v * a; reference = vec3(0.110000000, 0.220000000, 0.310000000); }
    if (column == 2) { calculated = (a * b) * v; reference = vec3(0.064000000, 0.119000000, 0.129000000); }
    if (column == 3) { calculated = (b * a) * v; reference = vec3(0.083000000, 0.131000000, 0.112000000); }
    if (column == 4) { calculated = (a * transpose(b)) * v; reference = vec3(0.090000000, 0.101000000, 0.127000000); }
    if (column == 5) { calculated = (inverse(a) * v) * 0.1; reference = vec3(0.080000000, 0.140000000, 0.140000000); }
    if (column == 6) { calculated = (mat4(a) * vec4(v, 1.0)).xyz; reference = vec3(0.130000000, 0.180000000, 0.330000000); }
    if (column == 7) { calculated = a[1] + a[2] * 0.25; reference = vec3(0.025000000, 0.300000000, 0.200000000); }
    vec3 color = UV.y < 0.4 ? calculated : reference;
    if (UV.y > 0.8 && UV.y < 0.9) { color = texture(nearest_map, UV * 3.0).rgb; }
    if (UV.y >= 0.9) { color = texture(linear_map, UV * 3.0).rgb; }
    SPECULAR = 0.0;
    ROUGHNESS = 0.7;
    ALBEDO = color * local_tint.rgb * step5_global.rgb * instance_tint.rgb * include_tint();
}

