extends Node2D

func _ready() -> void:
	print("MANUAL_CONSUMERS_READY canvas=ShaderMaterial particles=ParticleProcessMaterial amount=384 renderer=", RenderingServer.get_current_rendering_method(), " driver=", RenderingServer.get_current_rendering_driver_name())

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventKey and event.pressed and not event.echo:
		if event.keycode == KEY_ESCAPE:
			get_tree().quit()
		elif event.keycode == KEY_P:
			await RenderingServer.frame_post_draw
			var path := "user://consumers-%d.png" % Time.get_unix_time_from_system()
			var result := get_viewport().get_texture().get_image().save_png(path)
			print("MANUAL_CONSUMERS_CAPTURE path=", ProjectSettings.globalize_path(path), " result=", result, " frame=", Engine.get_frames_drawn())

