prepare_material.py.content:
from pathlib import Path
import json
import numpy as np

root = Path(__file__).parent
project = root / 'project'
a = np.array([[.2, 0, .1], [.1, .3, 0], [0, .1, .4]])
b = np.array([[.5, .1, 0], [.2, .4, .1], [.1, 0, .3]])
v = np.array([.3, .5, .7])
values = [a @ v, v @ a, (a @ b) @ v, (b @ a) @ v, (a @ b.T) @ v, (np.linalg.inv(a) @ v) * .1, a @ v, a[:, 1] + a[:, 2] * .25]
expressions = ['a * v', 'v * a', '(a * b) * v', '(b * a) * v', '(a * transpose(b)) * v', '(inverse(a) * v) * 0.1', '(mat4(a) * vec4(v, 1.0)).xyz', 'a[1] + a[2] * 0.25']
source = '''shader_type spatial;
#include "res://material_manual.gdshaderinc"
uniform mat3 basis_value;
uniform vec4 local_tint = vec4(1.0);
global uniform vec4 step5_global;
instance uniform vec4 instance_tint = vec4(1.0);
uniform sampler2D nearest_map : filter_nearest, repeat_enable;
uniform sampler2D linear_map : filter_linear, repeat_disable;
void fragment() {
    mat3 a = basis_value;
    mat3 b = mat3(vec3(0.5, 0.2, 0.1), vec3(0.1, 0.4, 0.0), vec3(0.0, 0.1, 0.3));
    vec3 v = vec3(0.3, 0.5, 0.7);
    int column = clamp(int(UV.x * 8.0), 0, 7);
    vec3 calculated = vec3(0.0);
    vec3 reference = vec3(0.0);
'''
for i, (expression, value) in enumerate(zip(expressions, values)):
    color = ', '.join(format(float(x), '.9f') for x in value)
    source += f'    if (column == {i}) {{ calculated = {expression}; reference = vec3({color}); }}\n'
source += '''    vec3 color = UV.y < 0.4 ? calculated : reference;
    if (UV.y > 0.8 && UV.y < 0.9) { color = texture(nearest_map, UV * 3.0).rgb; }
    if (UV.y >= 0.9) { color = texture(linear_map, UV * 3.0).rgb; }
    ALBEDO = vec3(0.0);
    SPECULAR = 0.0;
    ROUGHNESS = 0.7;
    EMISSION = color * local_tint.rgb * step5_global.rgb * instance_tint.rgb * include_tint();
}
'''
(project / 'material_manual.gdshader').write_text(source)
(root / 'matrix-reference.json').write_text(json.dumps(dict(method='NumPy double precision matrix arithmetic; observations only, no assertions', a=a.tolist(), b=b.tolist(), v=v.tolist(), operations=expressions, reference=[x.tolist() for x in values]), indent=2))
config = project / 'project.godot'
text = config.read_text().replace('RTXDI manual rendering demonstration', 'Shader unification STEP5 manual presentation')
text += '\n[shader_globals]\n\nstep5_global = {\n"type": "vec4",\n"value": Vector4(1, 1, 1, 1)\n}\n'
config.write_text(text)

