project/addons/manual_capture/plugin.gd.content:
@tool
extends EditorPlugin

var last_request := ""

func _enter_tree() -> void:
	set_process(true)
	if FileAccess.file_exists("res://editor-capture-request.txt"):
		last_request = FileAccess.get_file_as_string("res://editor-capture-request.txt")
	print("MANUAL_EDITOR_CAPTURE_READY write editor-capture-request.txt to capture")

func _process(_delta: float) -> void:
	if FileAccess.file_exists("res://editor-capture-request.txt"):
		var request := FileAccess.get_file_as_string("res://editor-capture-request.txt")
		if request != last_request:
			last_request = request
			var screen := request.get_slice(" ", 0)
			if screen == "2D" or screen == "3D":
				EditorInterface.set_main_screen_editor(screen)
			_capture.call_deferred()

func _capture() -> void:
	print("MANUAL_EDITOR_CAPTURE_REQUEST frame=", Engine.get_frames_drawn())
	RenderingServer.force_draw(false)
	var image := EditorInterface.get_base_control().get_viewport().get_texture().get_image()
	var path := "user://editor-manual-" + str(Time.get_unix_time_from_system()) + ".png"
	var result := image.save_png(path)
	print("MANUAL_EDITOR_CAPTURE path=", ProjectSettings.globalize_path(path), " result=", result, " size=", image.get_size(), " frame=", Engine.get_frames_drawn())
